import ast
src = open('xarray/core/merge.py').read()
tree = ast.parse(src)
fn = next(n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == 'merge_attrs')

class MergeError(Exception): pass
def compat_dict_union(a, b):
    for k in set(a) & set(b):
        if a[k] != b[k]: raise ValueError(k)
    return {**a, **b}
ns = {'compat_dict_union': compat_dict_union, 'dict_equiv': lambda a, b: a == b,
      'MergeError': MergeError, 'dict': dict}
exec(compile(ast.Module(body=[fn], type_ignores=[]), '<merge_attrs>', 'exec'), ns)
merge_attrs = ns['merge_attrs']

# issue reproducer semantics, on the real edited source
a1, a2 = {'a': 'b'}, {'a': 'c'}
out = merge_attrs([a1, a2], 'override')
assert out == {'a': 'b'}, out
out['a'] = 'd'
assert a1['a'] == 'b' and a2['a'] == 'c' and out['a'] == 'd', (a1, a2, out)
print('override: merged attrs independent of source ->', out, '| sources:', a1, a2)

# other branches unchanged in behavior
assert merge_attrs([], 'override') is None
assert merge_attrs([a1, a2], 'drop') == {}
assert merge_attrs([{'a': 1}, {'b': 2}], 'no_conflicts') == {'a': 1, 'b': 2}
try:
    merge_attrs([a1, a2], 'no_conflicts'); raise SystemExit('should have raised')
except MergeError: pass
assert merge_attrs([a1, a1], 'identical') == a1
print('drop / no_conflicts / identical branches: OK')
